function safeLoad(){try{return JSON.parse(localStorage.getItem('weekendClubProgress')||'{}')}catch{return {}}}
function saveProgress(key,value){const data=safeLoad();data[key]=value;localStorage.setItem('weekendClubProgress',JSON.stringify(data));updateProgress()}
function updateProgress(){const data=safeLoad();const count=[1,2,3,4,5].filter(n=>data['step'+n]).length;$('#homeProgressText').textContent=`${count} / 5 완료`;$('#homeProgressBar').style.width=`${count*20}%`;$$('.step-card').forEach(card=>card.classList.toggle('done',!!data['step'+card.dataset.step]))}
function isSpeakingActivityDone(n){return Boolean(safeLoad()[`step1Sub${n}`])}
function completeSpeakingActivity(n){if(n<1||n>4)return;const data=safeLoad();data[`step1Sub${n}`]=true;if([1,2,3,4].every(index=>data[`step1Sub${index}`]))data.step1=true;localStorage.setItem('weekendClubProgress',JSON.stringify(data));updateProgress();updateSequenceNavigation()}
function showToast(text){const toast=$('#toast');toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>toast.classList.remove('show'),2600)}
function speak(text,rate=0.88){if(!state.speechEnabled)return;if(!('speechSynthesis'in window)){showToast('이 브라우저에서는 듣기 기능을 사용할 수 없어요.');return}window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-US';utterance.rate=rate;const voices=window.speechSynthesis.getVoices();utterance.voice=voices.find(v=>v.lang==='en-US')||null;window.speechSynthesis.speak(utterance)}
function normalize(text){return text.toLowerCase().replace(/[^a-z0-9' ]/g,' ').replace(/\s+/g,' ').trim().replace(/i am/g,"i'm").replace(/going to walk the dog/g,'going to walk the dog')}
function similarity(a,b){const aa=normalize(a).split(' ').filter(Boolean),bb=normalize(b).split(' ').filter(Boolean);if(!aa.length)return 0;let matched=0;const used=new Set();for(const word of aa){const ix=bb.findIndex((candidate,index)=>candidate===word&&!used.has(index));if(ix>=0){matched++;used.add(ix)}}return Math.round(matched/Math.max(aa.length,bb.length)*100)}
function listenForSpeech(onResult,onEnd,button){const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){showToast('이 브라우저에서는 마이크를 사용할 수 없어요. 아래 입력칸을 사용해 주세요.');return null}const rec=new SpeechRecognition();rec.lang='en-US';rec.interimResults=true;rec.continuous=false;let finalText='';rec.onresult=event=>{let interim='';for(let i=event.resultIndex;i<event.results.length;i++){const text=event.results[i][0].transcript;if(event.results[i].isFinal)finalText+=text;else interim+=text}onResult((finalText+' '+interim).trim(),!!finalText)};rec.onerror=event=>{if(button)button.classList.remove('listening');showToast(event.error==='not-allowed'?'마이크 권한이 꺼져 있어요. 직접 입력으로 이어가요.':'음성 인식이 잠시 어려워요. 직접 입력으로 이어가요.');if(onEnd)onEnd(finalText,event.error)};rec.onend=()=>{if(button)button.classList.remove('listening');if(onEnd)onEnd(finalText,'end')};try{rec.start();if(button)button.classList.add('listening')}catch{showToast('마이크를 시작할 수 없어요. 직접 입력을 이용해 주세요.')}return rec}
function speakAndWait(text,rate=.84){if(!state.speechEnabled)return Promise.resolve(false);if(!('speechSynthesis'in window)||typeof SpeechSynthesisUtterance==='undefined'){showToast('이 브라우저에서는 음성 듣기를 사용할 수 없어요.');return Promise.resolve(false)}const synth=window.speechSynthesis;synth.cancel();return new Promise(resolve=>{let settled=false;const utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-US';utterance.rate=rate;utterance.voice=synth.getVoices().find(voice=>voice.lang==='en-US')||null;const timeout=setTimeout(()=>finish(false),Math.max(5000,Math.min(15000,text.split(/\s+/).length*620/rate)));function finish(ok){if(settled)return;settled=true;clearTimeout(timeout);resolve(ok)}utterance.onend=()=>finish(true);utterance.onerror=()=>finish(false);synth.speak(utterance)})}
function ensureDialoguePracticeFallback(){const actions=$('#dialogueActions');if(!actions||$('#dialoguePracticeFallback'))return;actions.insertAdjacentHTML('afterend',`<div class="dialogue-practice-fallback" id="dialoguePracticeFallback" hidden><label class="control-label" id="dialoguePracticePrompt" for="dialoguePracticeInput">마이크가 안 되면 들은 문장을 입력해요</label><div class="action-row"><input class="select-field" id="dialoguePracticeInput" placeholder="영어 문장 입력"><button class="secondary-button" data-action="dialogue-practice-submit">확인</button></div></div>`)}
function stopDialoguePractice(){state.dialoguePracticeRunId=(state.dialoguePracticeRunId||0)+1;state.dialoguePracticeActive=false;if(state.dialoguePracticeRecognition){try{state.dialoguePracticeRecognition.stop()}catch{}state.dialoguePracticeRecognition=null}if(state.dialoguePracticeResolve){const resolve=state.dialoguePracticeResolve;state.dialoguePracticeResolve=null;resolve('')}if('speechSynthesis'in window)window.speechSynthesis.cancel();const fallback=$('#dialoguePracticeFallback');if(fallback)fallback.hidden=true;$$('[data-action="generated-dialogue-practice"],[data-action="play-generated-dialogue"]').forEach(button=>button.disabled=false)}
function requestDialogueRepeat(sentence,button,runId){return new Promise(resolve=>{let completed=false,manualShown=false,recognition=null,timer;const finish=text=>{if(completed)return;completed=true;clearTimeout(timer);if(state.dialoguePracticeResolve===finish)state.dialoguePracticeResolve=null;state.dialoguePracticeRecognition=null;const fallback=$('#dialoguePracticeFallback');if(fallback)fallback.hidden=true;resolve(text||'')};const showManual=()=>{if(completed||manualShown)return;manualShown=true;clearTimeout(timer);if(recognition){try{recognition.stop()}catch{}state.dialoguePracticeRecognition=null}if(runId!==state.dialoguePracticeRunId){finish('');return}const fallback=$('#dialoguePracticeFallback');const prompt=$('#dialoguePracticePrompt');const input=$('#dialoguePracticeInput');if(prompt)prompt.textContent=`따라 말해보세요: ${sentence}`;if(input)input.value='';if(fallback)fallback.hidden=false;if(input)input.focus();state.dialoguePracticeResolve=finish};recognition=listenForSpeech((text,isFinal)=>{if(isFinal)finish(text)},(text)=>{if(text)finish(text);else showManual()},button);state.dialoguePracticeRecognition=recognition;state.dialoguePracticeResolve=finish;if(!recognition){showManual();return}timer=setTimeout(showManual,12000)})}
async function playDialogueSequence(practice){stopDialoguePractice();const runId=state.dialoguePracticeRunId;const action=practice?'[data-action="generated-dialogue-practice"]':'[data-action="play-generated-dialogue"]';const button=$(action);const lines=generatedDialogueLines();if(button)button.disabled=true;state.dialoguePracticeActive=true;for(let index=0;index<lines.length;index++){if(runId!==state.dialoguePracticeRunId)return;const line=lines[index];$('#dialogueFeedback').textContent=practice?`문장 ${index+1}/${lines.length}을 듣고 따라 말해보세요.`:`문장 ${index+1}/${lines.length}을 차례로 들려드려요.`;await speakAndWait(line.text,.84);if(runId!==state.dialoguePracticeRunId)return;if(practice){$('#dialogueFeedback').textContent='이제 문장을 말해보세요.';let answer=await requestDialogueRepeat(line.text,button,runId);if(runId!==state.dialoguePracticeRunId)return;let score=similarity(answer,line.text);if(score<65){$('#dialogueFeedback').textContent='괜찮아요. 한 번 더 천천히 말해봐요.';await speakAndWait(line.text,.76);if(runId!==state.dialoguePracticeRunId)return;answer=await requestDialogueRepeat(line.text,button,runId);if(runId!==state.dialoguePracticeRunId)return;score=similarity(answer,line.text)}$('#dialogueFeedback').textContent=score>=65?`${score}점! 다음 문장도 따라 말해봐요.`:'좋아요, 끝까지 따라 말했어요! 다음 문장으로 가볼게요.'}}state.dialoguePracticeActive=false;if(button)button.disabled=false;const fallback=$('#dialoguePracticeFallback');if(fallback)fallback.hidden=true;if(practice){$('#dialogueFeedback').textContent='대화를 끝까지 함께 읽었어요!';progressDone(2)}else $('#dialogueFeedback').textContent='대화를 끝까지 들었어요!'}
function renderHome(){stopCatchLoop();stopDialoguePractice();lesson.hidden=true;$('#homeView').hidden=false;window.scrollTo(0,0);updateProgress()}
function openSpeakingActivity(n){renderActivity(n)}
function sequenceNavMarkup(step){if(step===1){const sub=state.activity;const doneCount=[1,2,3,4].filter(isSpeakingActivityDone).length;const allDone=doneCount===4;const status=sub?`1-${sub} / 1-4 · ${doneCount}/4 완료`:`소단계 ${doneCount}/4 완료`;const previous=sub===1?'<button class="sequence-button sequence-previous" data-sequence-menu><span aria-hidden="true">←</span><span>소단계 목록</span></button>':sub>1?`<button class="sequence-button sequence-previous" data-sequence-activity="${sub-1}"><span aria-hidden="true">←</span><span>이전: 1-${sub-1}</span></button>`:'<button class="sequence-button sequence-previous" disabled><span aria-hidden="true">←</span><span>말하기 연습</span></button>';const next=sub===0?`<button class="sequence-button sequence-next" data-sequence-step="2" ${allDone?'':'disabled'}><span>${allDone?'다음 단계':'소단계 4개를 완료하세요'}</span><span aria-hidden="true">→</span></button>`:sub<4?`<button class="sequence-button sequence-next" data-sequence-activity="${sub+1}" ${isSpeakingActivityDone(sub)?'':'disabled'}><span>다음: 1-${sub+1}</span><span aria-hidden="true">→</span></button>`:`<button class="sequence-button sequence-next" data-sequence-step="2" ${allDone?'':'disabled'}><span>${allDone?'다음 단계':'소단계를 모두 완료하세요'}</span><span aria-hidden="true">→</span></button>`;const percent=sub?Math.round((Math.max(doneCount,sub-1)/4)*100):Math.round((doneCount/4)*100);return `<nav class="lesson-sequence-nav" aria-label="1단계 소단계 이동">${previous}<div class="sequence-status"><span>${status}</span><span class="sequence-progress"><i style="width:${percent}%"></i></span></div>${next}</nav>`}const previous=step-1;const next=step===5?0:step+1;return `<nav class="lesson-sequence-nav" aria-label="순차 학습 단계"><button class="sequence-button sequence-previous" data-sequence-step="${previous}"><span aria-hidden="true">←</span><span>이전 단계</span></button><div class="sequence-status"><span>STEP 0${step} / 05</span><span class="sequence-progress"><i style="width:${step*20}%"></i></span></div><button class="sequence-button sequence-next" data-sequence-step="${next}"><span>${step===5?'코스 마치기':'다음 단계'}</span><span aria-hidden="true">${step===5?'✓':'→'}</span></button></nav>`}
function sequenceNavigationMarkup(step){if(step===1){const sub=state.activity;const previous=sub===1?'<button class="sequence-button sequence-previous" data-sequence-menu><span aria-hidden="true">←</span><span>소단계 목록</span></button>':sub>1?`<button class="sequence-button sequence-previous" data-sequence-activity="${sub-1}"><span aria-hidden="true">←</span><span>이전: 1-${sub-1}</span></button>`:'<button class="sequence-button sequence-previous" disabled><span aria-hidden="true">←</span><span>이전</span></button>';const next=sub<4?`<button class="sequence-button sequence-next" data-sequence-activity="${sub+1}"><span>${sub===0?'1-1 시작':`다음: 1-${sub+1}`}</span><span aria-hidden="true">→</span></button>`:'<button class="sequence-button sequence-next" data-sequence-step="2"><span>다음 단계</span><span aria-hidden="true">→</span></button>';const status=sub?`1-${sub} / 1-4`:'1단계';return `<nav class="lesson-sequence-nav" aria-label="순차 학습 단계">${previous}<div class="sequence-status"><span>${status}</span><span class="sequence-progress"><i style="width:${sub*25}%"></i></span></div>${next}</nav>`}const previous=step===2?'<button class="sequence-button sequence-previous" data-sequence-activity="4"><span aria-hidden="true">←</span><span>이전: 1-4</span></button>':`<button class="sequence-button sequence-previous" data-sequence-step="${step-1}"><span aria-hidden="true">←</span><span>이전 단계</span></button>`;const next=step===5?0:step+1;return `<nav class="lesson-sequence-nav" aria-label="순차 학습 단계">${previous}<div class="sequence-status"><span>STEP 0${step} / 05</span><span class="sequence-progress"><i style="width:${step*20}%"></i></span></div><button class="sequence-button sequence-next" data-sequence-step="${next}"><span>${step===5?'코스 마치기':'다음 단계'}</span><span aria-hidden="true">${step===5?'✓':'→'}</span></button></nav>`}
function updateSequenceNavigation(){const nav=$('.lesson-sequence-nav');if(nav&&state.step===1)nav.outerHTML=sequenceNavigationMarkup(1)}
function shell(step,title,intro,body){if(step!==2)stopDialoguePractice();$('#homeView').hidden=true;lesson.hidden=false;const showGrammar=step===4||(step===1&&state.activity===2);lesson.innerHTML=`<div class="lesson-top"><button class="back-button" data-action="home">← 홈으로</button><div class="lesson-label">${UNIT.grade} · ${UNIT.lesson}<strong>STEP 0${step} / ${STEPS[step-1][0]}</strong></div></div><h1 class="lesson-title">${title}</h1><p class="lesson-intro">${intro}</p>${body}${showGrammar?grammarReference():''}${sequenceNavigationMarkup(step)}`;if(step===2)ensureDialoguePracticeFallback();lesson.scrollIntoView({behavior:'smooth',block:'start'})}
function progressDone(n){saveProgress('step'+n,true)}
function goStep(n){if(state.step===5&&n!==5)stopCatchLoop();state.step=n;state.quiz=null;state.quizIndex=0;if(n===1)renderStep1();if(n===2)renderDialogueStep();if(n===3){resetBattleSeries();renderStep3()}if(n===4){state.chatValidTurns=0;renderStep4()}if(n===5)renderStep5()}
function renderStep1(){state.step=1;state.activity=0;shell(1,'말하기 연습','듣고 말하며 주말 계획을 연습해요.',`<div class="subactivity-grid">${[['1-1','묻기','질문을 만들고 천천히 말해요.'],['1-2','답하기','주말 활동으로 나만의 문장을 만들어요.'],['1-3','되묻기','대화를 이어가는 질문을 연습해요.'],['1-4','반응하기','친구의 계획에 알맞게 답해요.']].map((x,i)=>{const n=i+1;const done=isSpeakingActivityDone(n);return `<button class="activity-card ${done?'is-complete':''}" data-activity="${n}"><span class="activity-index">${x[0]}</span><span class="step-arrow">${done?'✓':'↗'}</span><h3>${x[1]}</h3><p>${x[2]}</p></button>`}).join('')}</div><div class="lesson-card"><div class="card-heading"><div><h3>오늘의 핵심 표현</h3><p>세 번 소리 내어 읽어보세요.</p></div><span class="pill">SPEAKING</span></div><div class="sentence-display">${UNIT.question}<small>이번 주말에 뭐 할 거예요?</small></div><div class="action-row"><button class="secondary-button" data-speak="${UNIT.question}">▶ 듣기</button><button class="primary-button" data-activity="2">내 문장 만들기</button></div></div>`)}
function renderActivity(n){state.step=1;state.activity=n;const titles=['','묻기','답하기','되묻기','반응하기'];const intro=['','누구에게, 언제 할 일인지 골라 질문해요.','주말에 하고 싶은 일을 영어로 말해요.','질문 하나를 더하면 대화가 이어져요.','친구의 계획에 반응하는 표현을 연습해요.'][n];let body='';
 if(n===1)body=`<div class="lesson-card"><div class="field-row"><div class="field-group"><label class="control-label">누구의 계획을 물어볼까요?</label><div class="choice-row">${['you','he','she','they'].map(x=>`<button class="choice ${state.questionSubject===x?'selected':''}" data-subject="${x}">${x==='you'?'you':x==='he'?'he':x==='she'?'she':'they'}</button>`).join('')}</div></div><div class="field-group"><label class="control-label">언제 할 일을 물어볼까요?</label><div class="choice-row">${['this weekend','tomorrow','this Sunday'].map(x=>`<button class="choice ${state.questionTime===x?'selected':''}" data-time="${x}">${x}</button>`).join('')}</div></div></div><div class="sentence-display" id="questionPreview">${makeQuestion()}<small>${state.questionSubject==='you'?'이번 주말에 뭐 할 거예요?':'그/그녀는 이번 주말에 뭐 할 거예요?'}</small></div><div class="action-row"><button class="secondary-button" data-action="speak-question">▶ 천천히 듣기</button><button class="mic-button" data-action="practice-question">● 따라 말하기</button><span class="score-chip" id="practiceScore">말하기 점수 --</span></div><div class="inline-feedback" id="activityFeedback"></div><label class="control-label" for="questionTyped" style="margin-top:15px">마이크가 안 되면 문장을 직접 입력해도 좋아요</label><div class="action-row"><input class="select-field" id="questionTyped" placeholder="영어 문장을 입력해 보세요" style="flex:1"><button class="secondary-button" data-action="check-question">점수 확인</button></div></div>`;
 if(n===2)body=`<div class="lesson-card"><div class="field-row"><div class="field-group"><label class="control-label">문장 시작하기</label><div class="choice-row">${["I'm",'He is','She is',"We're"].map(x=>`<button class="choice ${state.answerSubject===x?'selected':''}" data-answer-subject="${x}">${x}</button>`).join('')}</div></div><div class="field-group" style="flex:1"><label class="control-label">주말에 무엇을 할까요?</label><select class="select-field" id="activitySelect">${UNIT.activities.map(x=>`<option ${state.activityWord===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="sentence-display" id="answerPreview">${makeAnswer()}<small>나는 ${translateActivity(state.activityWord)} 할 거예요.</small></div><div class="action-row"><button class="secondary-button" data-action="speak-answer">▶ 듣기</button><button class="mic-button" data-action="practice-answer">● 내 목소리로 말하기</button><span class="score-chip" id="answerScore">말하기 점수 --</span></div><div class="inline-feedback" id="activityFeedback"></div><label class="control-label" for="answerTyped" style="margin-top:15px">또박또박 직접 입력하고 점수를 확인할 수도 있어요</label><div class="action-row"><input class="select-field" id="answerTyped" placeholder="영어 문장을 입력해 보세요" style="flex:1"><button class="secondary-button" data-action="check-answer">점수 확인</button></div></div>`;
  if(n===3)body=`<div class="lesson-card"><div class="card-heading"><div><h3>대화를 이어주는 질문</h3><p>하나를 골라 듣고 따라 말해보세요.</p></div><span class="pill">YOUR TURN</span></div><div class="choice-row">${UNIT.followUps.map(x=>`<button class="choice ${state.follow===x?'selected':''}" data-follow="${x}">${x}</button>`).join('')}</div><div class="sentence-display" id="followPreview">${state.follow}<small>${translateFollowUp(state.follow)}</small></div><div class="action-row"><button class="secondary-button" data-action="speak-follow">▶ 듣기</button><button class="mic-button" data-action="practice-follow">● 따라 말하기</button><span class="score-chip" id="followScore">말하기 점수 --</span></div><div class="inline-feedback" id="activityFeedback"></div><label class="control-label" for="followTyped" style="margin-top:15px">직접 입력하기</label><div class="action-row"><input class="select-field" id="followTyped" placeholder="영어 질문을 입력해 보세요" style="flex:1"><button class="secondary-button" data-action="check-follow">점수 확인</button></div></div>`;
 if(n===4)body=`<div class="lesson-card"><div class="card-heading"><div><h3>기분 좋은 반응을 골라요</h3><p>친구가 강아지를 산책시킨대요. 뭐라고 할까요?</p></div><span class="pill">KIND WORDS</span></div><div class="choice-row">${UNIT.reactions.map(x=>`<button class="choice ${state.reaction===x?'selected':''}" data-reaction="${x}">${x}</button>`).join('')}</div><div class="sentence-display" id="reactionPreview">${state.reaction}<small>${translateReaction(state.reaction)}</small></div><div class="action-row"><button class="secondary-button" data-action="speak-reaction">▶ 듣기</button><button class="mic-button" data-action="practice-reaction">● 기분 좋게 말하기</button><span class="score-chip" id="reactionScore">말하기 점수 --</span></div><div class="inline-feedback" id="activityFeedback"></div><label class="control-label" for="reactionTyped" style="margin-top:15px">마이크가 안 되면 직접 입력해보세요</label><div class="action-row"><input class="select-field" id="reactionTyped" placeholder="Sounds great!" style="flex:1"><button class="secondary-button" data-action="check-reaction">점수 확인</button></div><div class="feedback-box"><h3>이런 말도 쓸 수 있어요</h3><p class="lesson-intro">“Sounds great!”은 “멋지다!”처럼 친구의 계획을 반기는 말이에요.</p></div></div>`;
  const activityBody=n===4?body.replace('기분 좋은 반응을 골라요','친구의 계획에 반응해요').replace('<p>친구가 강아지를 산책시킨대요. 뭐라고 할까요?</p>',''):body;shell(1,titles[n],intro,`<button class="back-button" data-action="step1" style="margin-top:14px">← 말하기 메뉴</button>${activityBody}`)}
function makeQuestion(){const subject=state.questionSubject==='he'||state.questionSubject==='she'?'is':'are';return `What ${subject} ${state.questionSubject} going to do ${state.questionTime}?`}
function makeAnswer(){const subject=state.answerSubject==='He is'?'He is':state.answerSubject==='She is'?'She is':state.answerSubject==="We're"?"We're":"I'm";return `${subject} going to ${state.activityWord}.`}
function translateActivity(word){return ({'walk the dog':'강아지를 산책시킬','see a movie':'영화를 볼','stay home':'집에서 쉴','play soccer':'축구를 할','visit my grandma':'할머니를 찾아뵐','read a book':'책을 읽을','ride a bike':'자전거를 탈','go shopping':'쇼핑을 할','have a picnic':'소풍을 갈','cook dinner':'저녁을 요리할','play board games':'보드게임을 할','go swimming':'수영을 할'})[word]||word}
function translateReaction(word){return ({'Sounds great!':'정말 좋은데!','Sure!':'물론이지!',"I can't wait!":'정말 기대돼!',"That's a good idea.":'정말 좋은 생각이야.','Sounds fun.':'재미있겠다.','Sounds good.':'좋아.'})[word]||''}
function translateFollowUp(word){return ({'How about you?':'너는 어때?','Can I come, too?':'나도 같이 가도 돼?','Do you want to come with me?':'나랑 같이 갈래?','Can you join?':'같이할 수 있어?','You can come along.':'너도 같이 가도 돼.'})[word]||'대화를 이어가는 표현이에요.'}
function placeTranslation(place){return ({'the park':'공원','the movie theater':'영화관',home:'집','the soccer field':'축구장','the shopping mall':'쇼핑몰',"my grandma's house":'할머니 댁','the pool':'수영장','the library':'도서관'})[place]||place}
function dialoguePlan(activity,place){if(activity==='stay home')return activity;if(activity==='visit my grandma')return 'visit my grandma at her house';return `${activity} at ${place}`}
function grammarReference(){return `<details class="grammar-reference"><summary>문법 참고표 보기</summary><div class="grammar-reference-body"><table class="grammar-table"><thead><tr><th>주어</th><th>be동사</th><th>줄임말</th></tr></thead><tbody><tr><td>I</td><td>am</td><td>I'm</td></tr><tr><td>He / She</td><td>is</td><td>He's / She's</td></tr><tr><td>You / We / They</td><td>are</td><td>You're / We're / They're</td></tr></tbody></table><p><b>be going to</b>: 미리 세운 계획을 말할 때 자주 써요.</p><p><b>will</b>: 말하는 순간의 결정이나 의지를 말할 때 쓸 수 있어요.</p><p class="grammar-note">두 표현은 문맥에 따라 쓰임이 겹치기도 해요.</p></div></details>`}
function scorePhrase(heard,target,scoreEl,feedbackEl){const score=similarity(heard,target);$(scoreEl).textContent=`말하기 점수 ${score}점`;$(feedbackEl).textContent=score>=85?'아주 또렷하게 말했어요! 멋져요!':score>=55?'잘했어요! 문장을 한 번 더 천천히 말해볼까요?':'도전한 것만으로도 잘했어요. 문장을 다시 듣고 한 번 더 말해봐요.';if(score>=85)showToast('참 잘했어요! 표현이 또렷하게 들렸어요.');if(state.step===1&&state.activity>=1&&state.activity<=4&&score>=55)completeSpeakingActivity(state.activity);return score}

function renderStep2(){state.dialogue={...state.dialogue};const d=state.dialogue;const body=`<div class="lesson-card"><div class="card-heading"><div><h3>우리의 주말 약속을 정해요</h3><p>장소와 친구, 활동을 골라 나만의 대화를 만들어요.</p></div><span class="pill">4+ SENTENCES</span></div><div class="field-row"><div class="field-group"><label class="control-label">장소</label><select class="select-field" id="dialoguePlace">${['the park','the movie theater','home','the soccer field'].map(x=>`<option ${d.place===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field-group"><label class="control-label">친구 이름</label><select class="select-field" id="dialogueName">${['Mina','Jin','Alex','Sora'].map(x=>`<option ${d.name===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field-group"><label class="control-label">언제</label><select class="select-field" id="dialogueTime">${['this weekend','on Sunday','tomorrow'].map(x=>`<option ${d.time===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field-row"><div class="field-group"><label class="control-label">함께 할 일</label><select class="select-field" id="dialogueActivity">${UNIT.activities.map(x=>`<option ${d.activity===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field-group"><label class="control-label">친구의 반응</label><select class="select-field" id="dialogueReaction">${UNIT.reactions.map(x=>`<option ${d.reaction===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="split-layout"><div class="panel"><h3>나의 대화</h3><div class="message-list" id="dialogueMessages"></div></div><div class="panel"><h3>미션 보드</h3><p class="lesson-intro">대화 속 핵심 표현을 듣고, 뜻을 확인하고, 직접 말해봐요.</p><div class="action-row" style="margin-top:12px"><button class="secondary-button" data-action="play-dialogue">▶ 전체 대화 듣기</button><button class="quiet-button" data-action="toggle-translations">해석 보기</button></div><div class="action-row" style="margin-top:9px"><button class="mic-button" data-action="dialogue-practice">● 대화 따라 읽기</button></div><div class="inline-feedback" id="dialogueFeedback"></div></div></div></div><div class="lesson-card" id="dialogueQuizCard"><div class="card-heading"><div><h3>대화 복습 미션</h3><p>이야기를 잘 기억했는지 확인해볼까요?</p></div><span class="pill">3 MINI GAMES</span></div><div class="choice-row"><button class="choice" data-quiz="ox">OX 퀴즈</button><button class="choice" data-quiz="order">순서 맞추기</button><button class="choice" data-quiz="odd">필요 없는 문장 찾기</button></div><div id="dialogueQuiz" class="inline-feedback">게임 하나를 골라 시작하세요.</div></div>`;shell(2,'대화글 만들기','내가 고른 주말 계획으로 짧은 대화를 완성해요.',body);updateDialogue()}
function renderDialogueStep(){state.dialogueGenerated=false;const d=state.dialogue;const places=Object.keys(DIALOGUE_PLANS);if(!places.includes(d.place))d.place=places[0];if(!DIALOGUE_PLANS[d.place].includes(d.activity))d.activity=DIALOGUE_PLANS[d.place][0];const placeOptions=places.map(place=>`<option value="${place}" ${d.place===place?'selected':''}>${place}</option>`).join('');const timeOptions=['this weekend','on Sunday','tomorrow'].map(time=>`<option value="${time}" ${d.time===time?'selected':''}>${time}</option>`).join('');const reactionOptions=UNIT.reactions.map(reaction=>`<option value="${reaction}" ${d.reaction===reaction?'selected':''}>${reaction}</option>`).join('');const body=`<div class="lesson-card"><div class="card-heading"><div><h3>우리의 주말 약속을 정해요</h3><p>장소와 할 일을 고르면 어울리는 표현으로 대화를 만들어요.</p></div><span class="pill">4+ SENTENCES</span></div><div class="field-row"><div class="field-group"><label class="control-label" for="dialoguePlaceNew">장소</label><select class="select-field" id="dialoguePlaceNew">${placeOptions}</select></div><div class="field-group"><label class="control-label" for="dialogueActivityNew">함께 할 일</label><select class="select-field" id="dialogueActivityNew"></select></div><div class="field-group"><label class="control-label" for="dialogueTimeNew">언제</label><select class="select-field" id="dialogueTimeNew">${timeOptions}</select></div><div class="field-group"><label class="control-label" for="dialogueReactionNew">내 반응</label><select class="select-field" id="dialogueReactionNew">${reactionOptions}</select></div></div><p class="dialogue-pair-hint" id="dialoguePairHint"></p><div class="action-row"><button class="primary-button" data-action="generate-dialogue">대화 생성하기</button></div><div class="split-layout"><div class="panel"><h3>우리의 대화</h3><div class="dialogue-placeholder" id="dialogueEmpty">선택을 마친 뒤 ‘대화 생성하기’를 눌러보세요.</div><div class="message-list" id="dialogueMessages" hidden></div></div><div class="panel"><h3>듣고 말해보기</h3><p class="lesson-intro">대화를 만든 뒤 문장별 듣기와 전체 따라 읽기를 할 수 있어요.</p><div class="action-row" id="dialogueActions" style="margin-top:12px" hidden><button class="secondary-button" data-action="play-generated-dialogue">▶ 전체 대화 듣기</button><button class="quiet-button" data-action="toggle-translations">해석 보기</button><button class="mic-button" data-action="generated-dialogue-practice">● 대화 따라 읽기</button></div><div class="inline-feedback" id="dialogueFeedback"></div></div></div></div><div class="lesson-card" id="dialogueQuizCard" hidden><div class="card-heading"><div><h3>대화 복습 미션</h3><p>완성한 대화를 기억하며 미니게임을 해봐요.</p></div><span class="pill">3 MINI GAMES</span></div><div class="choice-row"><button class="choice" data-dialogue-quiz="ox">OX 퀴즈</button><button class="choice" data-dialogue-quiz="order">순서 맞추기</button><button class="choice" data-dialogue-quiz="odd">필요 없는 문장 찾기</button></div><div id="dialogueQuiz" class="inline-feedback">게임 하나를 골라 시작하세요.</div></div>`;shell(2,'대화글 만들기','장소와 계획을 고른 뒤 대화 생성 버튼을 눌러 완성해요.',body);updateDialogueActivityOptions();updateDialoguePairHint()}
function updateDialogueActivityOptions(){const select=$('#dialogueActivityNew');if(!select)return;const activities=DIALOGUE_PLANS[state.dialogue.place];select.innerHTML=activities.map(activity=>`<option value="${activity}" ${state.dialogue.activity===activity?'selected':''}>${activity}</option>`).join('');if(!activities.includes(state.dialogue.activity))state.dialogue.activity=activities[0];select.value=state.dialogue.activity}
function updateDialoguePairHint(){const hint=$('#dialoguePairHint');if(hint)hint.textContent=`현재 조합: ${placeTranslation(state.dialogue.place)} + ${state.dialogue.activity}`;let examples=$('#dialoguePairExamples');if(!examples&&hint){examples=document.createElement('p');examples.id='dialoguePairExamples';examples.className='dialogue-pair-examples';hint.after(examples)}if(examples)examples.textContent='예: 공원 + 강아지 산책 · 영화관 + 영화 보기 · 집 + 책 읽기 · 축구장 + 축구하기 · 수영장 + 수영하기 · 쇼핑몰 + 쇼핑하기'}
function invalidateDialogue(){state.dialogueGenerated=false;state.quiz=null;state.quizIndex=0;$('#dialogueMessages').hidden=true;$('#dialogueEmpty').hidden=false;$('#dialogueActions').hidden=true;$('#dialogueQuizCard').hidden=true;$('#dialogueQuiz').textContent='게임 하나를 골라 시작하세요.';$('#dialogueFeedback').textContent=''}
function generatedDialogueLines(){const d=state.dialogue;const options=DIALOGUE_PLANS[d.place]||[d.activity];const friendActivity=options.find(activity=>activity!==d.activity)||d.activity;const studentPlan=dialoguePlan(d.activity,d.place);const friendPlan=dialoguePlan(friendActivity,d.place);const studentKo=d.activity==='stay home'?'집에서 쉴 거야':d.activity==='visit my grandma'?'할머니 댁에서 할머니를 찾아뵐 거야':`${placeTranslation(d.place)}에서 ${translateActivity(d.activity)} 거야`;const friendKo=friendActivity==='stay home'?'집에서 쉴 거야':friendActivity==='visit my grandma'?'할머니 댁에서 할머니를 찾아뵐 거야':`${placeTranslation(d.place)}에서 ${translateActivity(friendActivity)} 거야`;const when=d.time==='this weekend'?'이번 주말에':d.time==='on Sunday'?'일요일에':'내일';return [{who:'Mina',text:`Hi! What are you going to do ${d.time}?`,ko:`안녕! ${when} 뭐 할 거야?`},{who:'You',text:`I'm going to ${studentPlan}. How about you?`,ko:`나는 ${studentKo} 너는 어때?`},{who:'Mina',text:`I'm going to ${friendPlan}${friendActivity===d.activity?', too':''}.`,ko:`나는 ${friendKo}${friendActivity===d.activity?' 나도 그래.':''}`},{who:'You',text:`${d.reaction} Can I come, too?`,ko:`${translateReaction(d.reaction)} 나도 같이 가도 돼?`},{who:'Mina',text:'Sure! You can come along.',ko:'물론이지! 너도 같이 가도 돼.'}]}
function updateGeneratedDialogue(){const box=$('#dialogueMessages');if(!box)return;if(!state.dialogueGenerated){invalidateDialogue();return}const lines=generatedDialogueLines();$('#dialogueEmpty').hidden=true;box.hidden=false;$('#dialogueActions').hidden=false;$('#dialogueQuizCard').hidden=false;box.innerHTML=lines.map((line,index)=>`<div class="message ${line.who==='You'?'me':''}"><div class="message-bubble"><span class="speaker-name">${line.who}</span>${line.text}<span class="message-translation" hidden>${line.ko}</span></div><button class="message-action" data-generated-line="${index}" aria-label="문장 듣기">▶</button></div>`).join('')}
function startGeneratedQuiz(type){const lines=generatedDialogueLines();state.quiz=type;state.quizIndex=0;if(type==='ox')quizQuestions=[{q:`You plan to ${state.dialogue.activity}.`,a:true},{q:`Mina plans to ${DIALOGUE_PLANS[state.dialogue.place].find(activity=>activity!==state.dialogue.activity)||state.dialogue.activity}.`,a:true},{q:'The conversation is about weekend plans.',a:true},{q:'Mina says she is going to eat a purple cloud.',a:false}];if(type==='order')quizQuestions=lines.map((line,index)=>({q:line.text,a:index})).sort(()=>Math.random()-.5);if(type==='odd')quizQuestions=[...lines.slice(0,4).map((line,index)=>({q:line.text,a:index})),{q:'I am going to eat a purple cloud.',a:-1}].sort(()=>Math.random()-.5);showQuizQuestion()}
function dialogueLines(){const d=state.dialogue;return [{who:'Mina',text:`Hi! What are you going to do ${d.time}?`,ko:`안녕! ${d.time==='this weekend'?'이번 주말에':'그날'} 뭐 할 거야?`},{who:'You',text:`I'm going to ${d.activity} at ${d.place}.`,ko:`나는 ${d.place}에서 ${translateActivity(d.activity)} 거야.`},{who:'Mina',text:'How about you?',ko:'너는 어때?'},{who:'You',text:`I'm going to ${d.activity}, too.`,ko:`나도 ${translateActivity(d.activity)} 거야.`},{who:'Mina',text:d.reaction,ko:translateReaction(d.reaction)},{who:'You',text:'Can I come, too?',ko:'나도 같이 가도 돼?'}]}
function updateDialogue(){const box=$('#dialogueMessages');if(!box)return;box.innerHTML=dialogueLines().map((line,i)=>`<div class="message ${line.who==='You'?'me':''}"><div class="message-bubble"><span class="speaker-name">${line.who==='You'?'You':line.who}</span>${line.text}<span class="message-translation" hidden>${line.ko}</span></div><button class="message-action" data-line-speak="${i}" aria-label="문장 듣기">▶</button></div>`).join('')}
function startQuiz(type){const lines=dialogueLines();state.quiz=type;state.quizIndex=0;if(type==='ox')quizQuestions=[{q:`${state.dialogue.name} plans to ${state.dialogue.activity}.`,a:true},{q:'The conversation is about a plan for the weekend.',a:true},{q:'The friend says, “I do not like that plan.”',a:false}];if(type==='order')quizQuestions=lines.map((line,i)=>({q:line.text,a:i})).sort(()=>Math.random()-.5);if(type==='odd'){const choices=[...lines.slice(0,4).map((x,i)=>({q:x.text,a:i})),{q:'I am going to eat a purple cloud.',a:-1}].sort(()=>Math.random()-.5);quizQuestions=choices}showQuizQuestion()}
function showQuizQuestion(){const box=$('#dialogueQuiz');if(!box)return;if(state.quizIndex>=quizQuestions.length){box.innerHTML=`모두 맞혔어요! ${state.quiz==='ox'?'OX 퀴즈':state.quiz==='order'?'문장 순서':'다른 문장 찾기'} 미션 성공! <button class="quiet-button" data-action="retry-quiz">다시 하기</button>`;progressDone(2);return}const item=quizQuestions[state.quizIndex];if(state.quiz==='ox')box.innerHTML=`<b>Q${state.quizIndex+1}.</b> ${item.q}<div class="quiz-options"><button class="quiz-option" data-quiz-answer="true">O, 맞아요</button><button class="quiz-option" data-quiz-answer="false">X, 아니에요</button></div>`;else if(state.quiz==='order')box.innerHTML=`<b>대화 순서 ${state.quizIndex+1}/${quizQuestions.length}</b><p>${item.q}</p><div class="quiz-options">${quizQuestions.map((_,i)=>`<button class="quiz-option" data-quiz-answer="${i}">${i+1}번째</button>`).join('')}</div>`;else box.innerHTML=`<b>대화에 끼어든 문장을 찾아요 ${state.quizIndex+1}/${quizQuestions.length}</b><p>${item.q}</p><div class="quiz-options"><button class="quiz-option" data-quiz-answer="true">대화와 어울려요</button><button class="quiz-option" data-quiz-answer="false">다른 문장이에요</button></div>`}

const BATTLE_PHRASES=UNIT.activities.map(activity=>`I'm going to ${activity}.`);
function pickBattlePhrase(){const choices=BATTLE_PHRASES.filter(phrase=>!state.battleUsedPhrases.includes(phrase)&&phrase!==state.battleLastPhrase);const pool=choices.length?choices:BATTLE_PHRASES.filter(phrase=>phrase!==state.battleLastPhrase);const phrase=pool[Math.floor(Math.random()*pool.length)];state.battleUsedPhrases.push(phrase);state.battleLastPhrase=phrase;return phrase}
function resetBattleSeries(){state.battleRound=1;state.battleWins=0;state.battleLosses=0;state.battleUsedPhrases=[];state.battlePhrase=pickBattlePhrase();state.battleRoundDone=false}
function renderStep3(){const body=`<div class="lesson-card"><div class="card-heading"><div><h3>AI 친구보다 빠르고 또렷하게!</h3><p>문장을 보고 준비한 뒤, START!에서 큰 소리로 말해요.</p></div><span class="pill">5-ROUND MATCH</span></div><div class="battle-series-status"><strong id="battleRoundNumber">ROUND ${state.battleRound} / 5</strong><span id="battleSeriesScore">나 ${state.battleWins}승 · AI ${state.battleLosses}승</span></div><div class="battle-arena"><div class="battle-status" id="battleStatus">READY?</div><div class="battle-word" id="battlePhrase">${state.battlePhrase}</div><p class="lesson-intro" id="battleDescription">주말 계획을 영어로 말해보세요.</p><div class="battle-count" id="battleCount"></div><div class="battle-track"><span id="battleTrack"></span></div><div class="action-row" style="justify-content:center"><button class="primary-button" id="battleStart" data-action="start-battle">도전 시작!</button><button class="secondary-button" id="battleSpeak" data-speak="${state.battlePhrase}">▶ 문장 듣기</button></div></div><div class="field-row" style="margin-bottom:0"><div class="field-group" style="flex:1"><label class="control-label" for="battleInput">마이크가 안 되면 여기에 문장을 입력해요</label><input class="select-field" id="battleInput" style="width:100%" placeholder="말한 문장을 입력하고 결과를 확인하세요"></div><button class="secondary-button" id="battleSubmit" data-action="battle-submit" style="align-self:end">결과 확인</button></div><div class="inline-feedback" id="battleFeedback"></div><div class="action-row battle-next-row"><button class="primary-button" id="battleNext" data-action="next-battle-round" hidden>다음 라운드 →</button></div></div>`;shell(3,'AI 말하기 대결','영어 표현을 사용해서 AI 친구와 멋지게 겨뤄요.',body)}
function startBattle(){if(state.battleRoundDone)return;clearTimeout(state.battleTimer);clearTimeout(state.battleAiDelay);state.battleListening=false;$('#battleStart').disabled=true;$('#battleStatus').textContent='GET READY';$('#battleFeedback').textContent='';let count=3;$('#battleCount').textContent=count;$('#battleTrack').style.width='0%';const tick=()=>{count--;if(count>0){$('#battleCount').textContent=count;state.battleTimer=setTimeout(tick,700);return}$('#battleCount').textContent='GO!';$('#battleStatus').textContent='START!';const duration=6000+Math.random()*4000;state.battleAiDelay=setTimeout(()=>{if(!state.battleListening)finishBattle($('#battleInput').value.trim())},duration);const rec=listenForSpeech((text)=>{if(text)$('#battleInput').value=text},(text,error)=>{state.battleListening=false;if(error==='end'&&text){clearTimeout(state.battleAiDelay);finishBattle(text)}},null);state.battleListening=!!rec;showToast(rec?'START! 문장을 말해보세요.':'음성 입력을 사용할 수 없어요. 입력칸에 문장을 적어보세요. AI 도전은 계속돼요.');};tick()}
function finishBattle(text){clearTimeout(state.battleTimer);clearTimeout(state.battleAiDelay);if(!$('#battleStatus')||state.battleRoundDone)return;state.battleRoundDone=true;const score=text?similarity(text,state.battlePhrase):0;const aiScore=55+Math.floor(Math.random()*39);if(score>=aiScore)state.battleWins++;else state.battleLosses++;$('#battleStatus').textContent='ROUND COMPLETE';$('#battleCount').textContent=`${score} : ${aiScore}`;$('#battleTrack').style.width=`${score}%`;$('#battleSeriesScore').textContent=`나 ${state.battleWins}승 · AI ${state.battleLosses}승`;$('#battleFeedback').textContent=text?`이번 라운드: 내 점수 ${score}점 · AI ${aiScore}점${score>=aiScore?' · 이겼어요!':' · 다음 라운드에서 만회해요!'}`:'목소리를 듣지 못해 이번 라운드는 AI 점수로 기록했어요. 다음에는 직접 입력해도 괜찮아요.';$('#battleStart').disabled=true;$('#battleSubmit').disabled=true;if(state.battleRound<5){$('#battleNext').hidden=false;return}progressDone(3);showBattleModal(state.battleWins>state.battleLosses,state.battleWins,state.battleLosses)}
function nextBattleRound(){state.battleRound++;state.battlePhrase=pickBattlePhrase();state.battleRoundDone=false;$('#battleRoundNumber').textContent=`ROUND ${state.battleRound} / 5`;$('#battlePhrase').textContent=state.battlePhrase;$('#battleSpeak').dataset.speak=state.battlePhrase;$('#battleStatus').textContent='READY?';$('#battleCount').textContent='';$('#battleTrack').style.width='0%';$('#battleFeedback').textContent='새 문장이 준비됐어요. 준비되면 도전을 시작하세요.';$('#battleInput').value='';$('#battleStart').disabled=false;$('#battleSubmit').disabled=false;$('#battleNext').hidden=true}
function showBattleModal(win,wins,losses){const smiling=`<svg viewBox="0 0 120 120" aria-hidden="true"><path d="M20 17 25 8m69 6 6-8M8 76l-6 4m107-24 8-2" stroke="#edb84d" stroke-width="4" stroke-linecap="round"/><circle cx="60" cy="61" r="48" fill="#ffe17a" stroke="#efbd4e" stroke-width="3"/><path d="M38 51c2-7 8-7 10 0m24 0c2-7 8-7 10 0" fill="none" stroke="#51473e" stroke-width="4" stroke-linecap="round"/><circle cx="34" cy="66" r="6" fill="#f5a19b"/><circle cx="86" cy="66" r="6" fill="#f5a19b"/><path d="M42 70c4 18 32 18 36 0" fill="#fff" stroke="#51473e" stroke-width="4" stroke-linecap="round"/><path d="m42 77 36 0" stroke="#ed9d96" stroke-width="2"/></svg>`;const crying=`<svg viewBox="0 0 120 120" aria-hidden="true"><circle cx="60" cy="61" r="48" fill="#d8e8ff" stroke="#9ab8e8" stroke-width="3"/><path d="m37 48 11 4m35-4-11 4" stroke="#51473e" stroke-width="4" stroke-linecap="round"/><circle cx="43" cy="59" r="3" fill="#51473e"/><circle cx="77" cy="59" r="3" fill="#51473e"/><path d="M46 84c5-14 23-14 28 0" fill="none" stroke="#51473e" stroke-width="4" stroke-linecap="round"/><path d="M29 63c-4 9-7 15-7 20a8 8 0 0 0 16 0c0-5-4-12-9-20Zm69-2c-4 9-7 15-7 20a8 8 0 0 0 16 0c0-5-4-12-9-20Z" fill="#72b8e9"/></svg>`;const back=document.createElement('div');back.className='modal-backdrop';back.innerHTML=`<div class="modal ${win?'win':'lose'}" role="dialog" aria-modal="true" aria-labelledby="battleResultTitle"><div class="battle-result-art">${win?smiling:crying}</div><h2 id="battleResultTitle">${win?'WIN!':'LOSE!'}</h2><p>${win?'5라운드 대결에서 이겼어요! 정말 멋져요.':'이번 대결은 아쉽게 졌어요. 다시 도전해봐요!'}<br>최종 결과: 나 ${wins}승 · AI ${losses}승</p><div class="action-row"><button class="secondary-button" data-modal-close>결과 보기</button><button class="primary-button" data-modal-retry>다른 문장으로 재도전</button></div></div>`;document.body.append(back);back.addEventListener('click',e=>{if(e.target===back||e.target.closest('[data-modal-close]'))back.remove();if(e.target.closest('[data-modal-retry]')){back.remove();resetBattleSeries();renderStep3()}})}

function renderStep4(){state.feedbackText='';state.chatPromptKind='plan';state.chatPrompt=UNIT.question;state.chatActivity='';state.chatDetailCount=0;state.chatHistory=[];const body=`<div class="lesson-card"><div class="card-heading"><div><h3>Bobo AI와 주말 계획 이야기</h3><p>영어로 답해보세요. 답변에 나온 계획을 살려 문장을 다듬어드려요.</p></div><span class="pill">UPSTAGE AI</span></div><div class="chat-shell"><div class="chat-head"><span class="chat-avatar">B</span><div><strong>Bobo AI</strong><span>주말 계획 영어 연습</span></div><span class="chat-online" id="chatStatus">● 연결 확인 중</span></div><div class="chat-messages" id="chatMessages" role="log" aria-live="polite"><div class="chat-message assistant"><span class="chat-avatar">B</span><div class="chat-message-body"><span class="chat-name">Bobo AI</span><div class="chat-bubble">${UNIT.question}<small>이번 주말에 무엇을 할 계획인가요?</small></div></div></div></div><div class="chat-compose"><div class="chat-compose-controls"><button class="secondary-button" id="chatListen" data-speak="${UNIT.question}">▶ 질문 듣기</button><button class="mic-button" data-action="feedback-mic">● 말하기</button></div><textarea class="chat-textarea" id="feedbackInput" rows="2" placeholder="예: I'm going to play soccer."></textarea><div class="chat-send-row"><span>영어로 편하게 답해보세요.</span><button class="primary-button" data-action="analyze-feedback">보내기 ↑</button></div></div></div><div id="chatPractice"></div></div>`;shell(4,'AI 평가하기','Bobo AI의 질문에 답하며 대화를 이어가고, 내 문장을 직접 고쳐봐요.',body);checkAiStatus()}
async function checkAiStatus(){try{const response=await fetch('/api/status');const status=await response.json();const badge=$('#chatStatus');if(badge)badge.textContent=status.configured?'● Upstage AI 연결됨':'● 기본 평가 모드'}catch{const badge=$('#chatStatus');if(badge)badge.textContent='● 기본 평가 모드'}}
function addChatMessage(role,text,translation=''){const log=$('#chatMessages');const row=document.createElement('div');row.className=`chat-message ${role}`;if(role==='assistant'){const avatar=document.createElement('span');avatar.className='chat-avatar';avatar.textContent='B';row.append(avatar)}const body=document.createElement('div');body.className='chat-message-body';const name=document.createElement('span');name.className='chat-name';name.textContent=role==='assistant'?'Bobo AI':'나';const bubble=document.createElement('div');bubble.className='chat-bubble';bubble.textContent=text;if(translation){const sub=document.createElement('small');sub.textContent=translation;bubble.append(sub)}body.append(name,bubble);row.append(body);log.append(row);log.scrollTop=log.scrollHeight;return bubble}
const ACTION_BASES={walking:'walk',walked:'walk',walks:'walk',playing:'play',played:'play',plays:'play',seeing:'see',saw:'see',sees:'see',staying:'stay',stayed:'stay',stays:'stay',visiting:'visit',visited:'visit',visits:'visit',reading:'read',reads:'read',riding:'ride',rode:'ride',rides:'ride',going:'go',went:'go',goes:'go',shopping:'shop',shopped:'shop',watching:'watch',watched:'watch',watches:'watch',studying:'study',studied:'study',cooking:'cook',cooked:'cook',drawing:'draw',drew:'draw',helping:'help',helped:'help',swimming:'swim',swam:'swim',running:'run',ran:'run',eating:'eat',ate:'eat',meeting:'meet',met:'meet',practicing:'practice',practiced:'practice',dancing:'dance',danced:'dance',singing:'sing',sang:'sing',writing:'write',wrote:'write',painting:'paint',painted:'paint',cleaning:'clean',cleaned:'clean',making:'make',made:'make',having:'have',had:'have',traveling:'travel',travelled:'travel',cycling:'cycle',biking:'bike',skating:'skate',skated:'skate',camping:'camp',camped:'camp'};
const ACTION_VERBS=new Set(['walk','play','see','stay','visit','read','ride','go','shop','watch','study','cook','draw','help','swim','run','eat','meet','practice','do','dance','sing','write','paint','clean','make','have','travel','cycle','bike','skate','camp','sleep','work','fish','listen','take']);
function extractAction(text){if(/\b(?:don't|do not|doesn't|hate|hate you)\b/i.test(text))return null;const source=text.replace(/[.!?,;:]/g,' ').trim().split(/\s+/);const lower=source.map(word=>word.toLowerCase().replace(/[^a-z']/g,''));for(let i=0;i<lower.length;i++){let start=i;if(lower[i]==='going'&&lower[i+1]==='to')start=i+2;else if(['gonna','will'].includes(lower[i]))start=i+1;const token=lower[start];const base=ACTION_BASES[token]||token;if(ACTION_VERBS.has(base)){const phrase=[base,...source.slice(start+1)].join(' ').trim();return {phrase,verb:base,form:token}}}return null}
function detectActivity(text,phrase){const value=`${text} ${phrase}`.toLowerCase();if(/walk(?:ing|ed|s)?\s+(?:the\s+)?dog|\bdog\b/.test(value))return 'walk the dog';if(/movie|cinema|film/.test(value))return 'see a movie';if(/stay(?:ing|ed|s)?\s+home|\bhome\b/.test(value))return 'stay home';if(/soccer|football/.test(value))return 'play soccer';if(/grandma|grandmother/.test(value))return 'visit my grandma';if(/read(?:ing|s)?\s+(?:a\s+)?book|\bbook\b/.test(value))return 'read a book';if(/bike|bicycle|cycling/.test(value))return 'ride a bike';if(/shopping|\bshop\b|\bmall\b/.test(value))return 'go shopping';return phrase}
function subjectFor(text){const first=text.trim().toLowerCase();if(/^(he|she)\b/.test(first))return first.startsWith('he')?'He is':'She is';if(/^(we|we're|we are)\b/.test(first))return "We're";if(/^(they|they're|they are)\b/.test(first))return "They're";if(/^(you|you're|you are)\b/.test(first))return "You're";return "I'm"}
function polishPlanPhrase(phrase){let result=phrase.trim();if(/^walk\s+dog\b/i.test(result))result=result.replace(/^walk\s+dog/i,'walk the dog');if(/^see\s+movie\b/i.test(result))result=result.replace(/^see\s+movie/i,'see a movie');if(/^read\s+book\b/i.test(result))result=result.replace(/^read\s+book/i,'read a book');if(/^ride\s+bike\b/i.test(result))result=result.replace(/^ride\s+bike/i,'ride a bike');if(/^visit\s+grandma\b/i.test(result))result=result.replace(/^visit\s+grandma/i,'visit my grandma');if(/^(shop|shopping)$/i.test(result))result='go shopping';return result}
function planFeedback(text,action){const normalized=text.toLowerCase();const hasSubject=/^(?:i|i'm|i am|he|she|we|they|you)\b/.test(normalized.trim());const future=/\bgoing\s+to\b|\bgonna\b|\bwill\b|\bplanning\s+to\b/i.test(text);const bePresent=/\b(?:am|is|are|'m|'re)\b/i.test(text);const baseForm=action.form===action.verb;const notes=[];let score=0;if(hasSubject){score+=30;notes.push('주어를 넣어 누가 할 일인지 잘 알려줬어요.')}else notes.push('문장 앞에 “I’m”처럼 주어와 be동사를 넣어봐요.');if(future&&bePresent){score+=35;notes.push('미래 계획을 나타내는 표현을 사용했어요.')}else notes.push('주말 계획은 “be going to + 동사원형”으로 말해요.');if(baseForm){score+=25;notes.push('동사원형을 잘 사용했어요.')}else{score+=10;notes.push(`“${action.form}”을 동사원형 “${action.verb}”으로 고치면 더 정확해요.`)}if(/\bwill\b/i.test(text))notes.push('will은 말하는 순간의 결정·의지, be going to는 미리 세운 계획에 자주 써요. 문맥에 따라 쓰임이 겹치기도 해요.');const subject=subjectFor(text);const phrase=polishPlanPhrase(action.phrase);return {score,correct:`${subject} going to ${phrase}.`,activity:detectActivity(text,phrase),notes}}
function analyzeSentence(text,context){const cleaned=text.trim();if(/\b(?:idiot|stupid|shut up|go away|leave me alone|hate you)\b|바보|꺼져|싫어/i.test(cleaned))return {onTopic:false,score:0,correct:'',activity:'',notes:[]};const action=extractAction(cleaned);if(action){const result=planFeedback(cleaned,action);if(context.kind==='activity-detail')result.correct=`I'm going to ${action.phrase} with my grandma.`;return {...result,onTopic:true}}
 const value=cleaned.toLowerCase();const activity=context.activity||state.chatActivity;const finish=(phrase,notes)=>({onTopic:true,score:85,correct:`I'm going to ${phrase}.`,activity,notes});
 if(context.kind==='location'&&/\b(park|home|school|beach|library|mall|field|playground|house|garden|pool|stadium|store)\b/.test(value)){let place=cleaned.replace(/[.!?]+$/,'').trim();if(/^(park|field|beach|library|mall|playground|garden|pool|stadium|store)$/i.test(place))place=`the ${place}`;if(!/^(at|in|on|near)\b/i.test(place))place=activity==='stay home'?'at home':`at ${place}`;const sentence=activity==='stay home'&&/home/i.test(place)?'stay home':`${activity} ${place}`;return finish(sentence,['장소를 잘 골랐어요. 계획과 장소를 한 문장으로 연결했어요.'])}
 if(context.kind==='companion'&&/\b(friend|friends|mom|mother|dad|father|family|brother|sister|grandma|grandmother|classmate|alone|my team)\b/.test(value)){let person=cleaned.replace(/[.!?]+$/,'').trim();if(!/^(with|alone)\b/i.test(person))person=/^alone$/i.test(person)?'alone':`with ${person}`;return finish(`${activity} ${person}`,['누구와 함께할지 대답했어요. 전체 계획 문장으로 자연스럽게 이어봤어요.'])}
 if(context.kind==='time'&&/\b(morning|afternoon|evening|night|saturday|sunday|weekend|tomorrow|today|noon|o'clock|am|pm|before|after|at\s+\d|on\s+\w+)/i.test(value)){let time=cleaned.replace(/[.!?]+$/,'').trim();if(/^(saturday|sunday|this weekend|tomorrow|today)\b/i.test(time))time=`on ${time}`;else if(!/^(at|in|on|this|next|tomorrow|before|after)\b/i.test(time))time=`in the ${time}`;return finish(`${activity} ${time}`,['언제 할 계획인지 구체적으로 덧붙였어요.'])}
 if(context.kind==='book'&&cleaned.length>1)return finish(`read ${cleaned.replace(/[.!?]+$/,'').trim()}`,['읽고 싶은 책을 골랐어요. 제목을 계획 문장에 넣어봤어요.']);
 if(context.kind==='buy'&&cleaned.length>1)return finish(`buy ${cleaned.replace(/[.!?]+$/,'').trim()}`,['무엇을 살지 구체적으로 말했어요.']);
 return {onTopic:false,score:0,correct:'',activity:'',notes:[]}}
function appendChatFeedback(result){const bubble=addChatMessage('assistant',result.feedback||(result.score>=75?'좋은 계획이에요! 하고 싶은 활동을 잘 알려줬어요. 문장 모양을 살짝 다듬어볼게요.':'말하려는 계획을 잘 찾았어요. 이번 단원의 표현으로 바꾸면 더 정확해져요.'));const score=document.createElement('span');score.className='chat-score';score.textContent=`문장 구성 ${result.score}점`;bubble.append(score)}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function showFeedback(result){state.recommendation=result.correct;state.chatValidTurns=(state.chatValidTurns||0)+1;if(state.chatValidTurns>=3)progressDone(4);appendChatFeedback(result);if(!needsSentencePractice(state.feedbackText,state.chatPromptKind))return;const area=$('#chatPractice');area.innerHTML=`<div class="feedback-box"><div class="card-heading"><div><h3>내 답변을 바탕으로 문장 다듬기</h3><p>학생이 말한 활동과 정보를 그대로 살렸어요.</p></div><span class="score-chip">${result.score}점</span></div><ul class="feedback-list">${result.notes.map(note=>`<li>${escapeHtml(note)}</li>`).join('')}</ul><div class="sentence-display" id="recommendationText">${escapeHtml(result.correct)}<small>고친 문장을 듣고 따라 말해보세요.</small></div><div class="action-row"><button class="secondary-button" data-action="speak-recommendation">▶ 문장 듣기</button><button class="mic-button" data-action="practice-recommendation">● 따라 말하기</button></div><div class="inline-feedback" id="recommendFeedback"></div><div id="dragGame"></div></div>`;renderDragGame();area.scrollIntoView({behavior:'smooth',block:'nearest'})}
function nextChatQuestion(result,previousKind){if(previousKind==='plan'||previousKind==='extra-plan'){state.chatActivity=result.activity;state.chatDetailCount=0;const questions={'walk the dog':{question:'Where are you going to walk the dog?',ko:'어디에서 강아지를 산책시킬 거예요?',kind:'location'},'see a movie':{question:'Who are you going to see a movie with?',ko:'누구와 영화를 볼 거예요?',kind:'companion'},'stay home':{question:'Who are you going to spend time with at home?',ko:'집에서 누구와 시간을 보낼 거예요?',kind:'companion'},'play soccer':{question:'Where are you going to play soccer?',ko:'어디에서 축구를 할 거예요?',kind:'location'},'visit my grandma':{question:'What are you going to do with your grandma?',ko:'할머니와 무엇을 할 거예요?',kind:'activity-detail'},'read a book':{question:'Where are you going to read?',ko:'어디에서 책을 읽을 거예요?',kind:'location'},'ride a bike':{question:'Where are you going to ride your bike?',ko:'어디에서 자전거를 탈 거예요?',kind:'location'},'go shopping':{question:'Who are you going to go shopping with?',ko:'누구와 쇼핑하러 갈 거예요?',kind:'companion'}};return questions[state.chatActivity]||{question:`Where are you going to ${state.chatActivity}?`,ko:'어디에서 할 계획인가요?',kind:'location'}}if(state.chatDetailCount===0){state.chatDetailCount=1;return {question:'When are you going to do that?',ko:'그 계획은 언제 할 거예요?',kind:'time'}}state.chatDetailCount=0;return {question:'What else are you going to do this weekend?',ko:'이번 주말에 또 무엇을 할 거예요?',kind:'extra-plan'}}
const CHAT_KINDS=new Set(['plan','location','companion','time','activity-detail','extra-plan']);
function responseAnchors(text){const ignored=new Set(['im',"i'm",'i','am','is','are','he','she','we','they','you','going','to','the','a','an','my','your','our','this','that','at','in','on','with','for','of','do','does','will','would','can','could','be','it','me','and','or','but','weekend','please',...ACTION_VERBS,...Object.keys(ACTION_BASES)]);return normalize(text).split(' ').filter(word=>word&&!ignored.has(word))}
function groundedCorrection(text,proposal,fallback){if(!proposal)return fallback;const anchors=responseAnchors(fallback||text);if(!anchors.length)return proposal;const proposed=new Set(normalize(proposal).split(' '));return anchors.every(word=>proposed.has(word))?proposal:fallback}
function mergeGrammarNotes(text,aiNotes,localNotes){const notes=aiNotes?.length?[...aiNotes]:[...localNotes];if(/\bwill\b/i.test(text)&&!notes.some(note=>note.includes('겹치'))){notes.push('두 표현은 문맥에 따라 쓰임이 겹치기도 해요.')}return notes.slice(0,4)}
function isCorrectPlanAnswer(text){const action=extractAction(text);if(!action||action.form!==action.verb)return false;const value=text.trim();const goingTo=/^(?:i'm|i am|he is|she is|we're|we are|they're|they are|you're|you are)\s+going to\b/i.test(value);const will=/^(?:i|he|she|we|they|you)\s+will\b|^(?:i'll|he'll|she'll|we'll|they'll|you'll)\b/i.test(value);return goingTo||will}
function needsSentencePractice(text,kind){if(kind==='plan'||kind==='extra-plan')return !isCorrectPlanAnswer(text);const fullSubject=/^(?:i|i'm|i am|he|she|we|they|you)\b/i.test(text.trim());return Boolean(fullSubject&&extractAction(text)&&!isCorrectPlanAnswer(text))}
async function sendChatMessage(){const input=$('#feedbackInput');const button=$('[data-action="analyze-feedback"]');const text=input.value.trim();if(!text){showToast('영어로 한 문장 말하거나 입력해 주세요.');input.focus();return}state.feedbackText=text;addChatMessage('student',text);input.value='';$('#chatPractice').innerHTML='';input.disabled=true;button.disabled=true;const context={kind:state.chatPromptKind,activity:state.chatActivity};const localResult=analyzeSentence(text,context);const typing=addChatMessage('assistant','잠깐만요, 문장을 살펴보고 있어요.');typing.closest('.chat-message').classList.add('typing');let aiResult=null;try{const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:[...state.chatHistory,{role:'user',content:text}],currentQuestion:state.chatPrompt,questionKind:state.chatPromptKind})});if(!response.ok)throw new Error('Upstage request failed');aiResult=await response.json()}catch{showToast('Upstage에 연결되지 않아 기본 피드백으로 이어갈게요.')}finally{typing.closest('.chat-message')?.remove();input.disabled=false;button.disabled=false}state.chatHistory.push({role:'user',content:text});const locallyRelevant=localResult.onTopic;const aiRelevant=Boolean(aiResult?.onTopic&&aiResult.corrected);if(!locallyRelevant&&!aiRelevant){const feedback=aiResult?.feedback||'답변 고마워요! 지금은 Lesson 9의 주말 계획을 영어로 말하는 연습 중이에요. “I’m going to ...”로 이번 주말 계획을 말해볼까요?';const follow=aiResult?.followUp||state.chatPrompt;addChatMessage('assistant',feedback,aiResult?.followUpKo||'수업 주제와 관련된 영어 문장으로 다시 답해보세요.');addChatMessage('assistant',follow,follow===UNIT.question?'이번 주말에 무엇을 할 계획인가요?':'질문에 맞는 짧은 영어 대답도 좋아요.');state.chatHistory.push({role:'assistant',content:`${feedback}\n${follow}`});state.chatPrompt=follow;$('#chatListen').dataset.speak=follow;return}if(aiResult&&!aiResult.onTopic&&!locallyRelevant){const feedback=aiResult.feedback||'주말 계획과 관련된 답변으로 다시 연습해볼까요?';const follow=aiResult.followUp||state.chatPrompt;addChatMessage('assistant',feedback,aiResult.followUpKo||'수업 주제로 돌아와 볼까요.');addChatMessage('assistant',follow);state.chatHistory.push({role:'assistant',content:`${feedback}\n${follow}`});state.chatPrompt=follow;$('#chatListen').dataset.speak=follow;return}const corrected=groundedCorrection(text,aiResult?.corrected,localResult.correct);if(!corrected){const feedback=aiResult?.feedback||'주말 계획을 영어 문장으로 말해볼까요?';addChatMessage('assistant',feedback);state.chatHistory.push({role:'assistant',content:feedback});return}const result={onTopic:true,score:aiResult?.score??localResult.score,correct:corrected,activity:localResult.activity||aiResult?.activity||'',notes:mergeGrammarNotes(text,aiResult?.notes,localResult.notes),feedback:aiResult?.feedback||''};showFeedback(result);state.chatHistory.push({role:'assistant',content:`${result.feedback}\nCorrected sentence: ${result.correct}`});const fallbackNext=nextChatQuestion(result,context.kind);const validAiFollowUp=aiResult?.onTopic&&CHAT_KINDS.has(aiResult.followUpKind)&&aiResult.followUp;const next=validAiFollowUp?{question:aiResult.followUp,ko:aiResult.followUpKo||'',kind:aiResult.followUpKind}:fallbackNext;state.chatPromptKind=next.kind;state.chatPrompt=next.question;addChatMessage('assistant',next.question,next.ko);state.chatHistory.push({role:'assistant',content:`Follow-up question: ${next.question}`});$('#chatListen').dataset.speak=next.question}
function hasEnglishPlanExample(text){const value=String(text||'').replace(/[’‘]/g,"'");const badAfterTo=new RegExp(`\\bgoing to\\s+(?:${Object.keys(ACTION_BASES).join('|')})\\b`,'i');return /\b(?:i'm|i am|he is|she is|we're|we are|they're|they are|you're|you are)\s+(?:(?:going to|will)\s+\w+|\w+ing\s+\w+)/i.test(value)||badAfterTo.test(value)}
function isValidPlanSentence(text){const match=String(text||'').trim().match(/^(?:i'm|i am|he is|she is|we're|we are|they're|they are|you're|you are)\s+going to\s+([a-z]+)\b/i);if(!match)return false;const verb=match[1].toLowerCase();return ACTION_VERBS.has(verb)||Object.values(ACTION_BASES).includes(verb)}
function safeEvaluationFeedback(feedback,score){if(typeof feedback==='string'&&feedback.trim()&&!hasEnglishPlanExample(feedback))return feedback;return score===0?'답변 고마워요! 지금은 주말 계획을 영어로 말하는 연습을 하고 있어요. 주제에 맞는 문장으로 다시 답해볼까요?':score>=70?'좋은 계획이에요! 말한 활동을 살려 문장을 다듬었어요.':'답변에 담긴 계획을 확인했어요. 고친 문장을 살펴봐요.'}
function safeEvaluationNotes(aiNotes,localNotes,text){const aiSafeNotes=Array.isArray(aiNotes)?aiNotes.filter(note=>typeof note==='string'&&!hasEnglishPlanExample(note)):[];const notes=localNotes.length?localNotes:aiSafeNotes;return mergeGrammarNotes(text,notes,localNotes)}
async function submitStudentAnswer(){const input=$('#feedbackInput');const button=$('[data-action="analyze-feedback"]');const text=input.value.trim();if(!text){showToast('영어로 한 문장 말하거나 입력해 주세요.');input.focus();return}state.feedbackText=text;addChatMessage('student',text);input.value='';$('#chatPractice').innerHTML='';input.disabled=true;button.disabled=true;const context={kind:state.chatPromptKind,activity:state.chatActivity};const localResult=analyzeSentence(text,context);const typing=addChatMessage('assistant','잠깐만요, 문장을 살펴보고 있어요.');typing.closest('.chat-message').classList.add('typing');let aiResult=null;try{const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:[...state.chatHistory,{role:'user',content:text}],currentQuestion:state.chatPrompt,questionKind:state.chatPromptKind})});if(!response.ok)throw new Error('Upstage request failed');aiResult=await response.json()}catch{showToast('Upstage에 연결되지 않아 기본 피드백으로 이어갈게요.')}finally{typing.closest('.chat-message')?.remove();input.disabled=false;button.disabled=false}state.chatHistory.push({role:'user',content:text});const candidate=groundedCorrection(text,aiResult?.corrected,localResult.correct||'');const validAiAnswer=Boolean(aiResult?.onTopic&&isValidPlanSentence(candidate));if(!localResult.onTopic&&!validAiAnswer){const feedback=safeEvaluationFeedback(aiResult?.feedback,0)||'답변 고마워요! 주말 계획에 관한 영어 문장으로 다시 말해볼까요?';const follow=state.chatPrompt;addChatMessage('assistant',feedback,'이번 단원의 주말 계획 표현으로 답해보세요.');addChatMessage('assistant',follow,follow===UNIT.question?'이번 주말에 무엇을 할 계획인가요?':'질문에 맞는 짧은 영어 대답도 좋아요.');state.chatHistory.push({role:'assistant',content:`${feedback}\n${follow}`});$('#chatListen').dataset.speak=follow;return}const corrected=isValidPlanSentence(localResult.correct)?localResult.correct:validAiAnswer?candidate:'';if(!corrected){const feedback='주말 계획을 “be going to + 동사원형”으로 다시 말해볼까요?';addChatMessage('assistant',feedback);state.chatHistory.push({role:'assistant',content:feedback});return}const result={onTopic:true,score:aiResult?.score??localResult.score,correct:corrected,activity:localResult.activity||aiResult?.activity||'',notes:safeEvaluationNotes(aiResult?.onTopic?aiResult.notes:null,localResult.notes,text),feedback:safeEvaluationFeedback(aiResult?.feedback,aiResult?.score??localResult.score)};showFeedback(result);state.chatHistory.push({role:'assistant',content:`${result.feedback}\nCorrected sentence: ${result.correct}`});const next=nextChatQuestion(result,context.kind);state.chatPromptKind=next.kind;state.chatPrompt=next.question;addChatMessage('assistant',next.question,next.ko);state.chatHistory.push({role:'assistant',content:`Follow-up question: ${next.question}`});$('#chatListen').dataset.speak=next.question}
function renderDragGame(){const words=state.recommendation.replace(/[.!?]/g,'').split(' ');state.dragWords=[...words].sort(()=>Math.random()-.5);state.placedWords=[];$('#dragGame').innerHTML=`<div class="feedback-box"><h3>단어를 순서대로 배열해요</h3><p class="lesson-intro">단어를 눌러 옮기거나 끌어서 아래 칸에 놓으세요.</p><div class="drag-bank" id="dragBank">${state.dragWords.map((w,i)=>`<button class="word-chip" draggable="true" data-word-index="${i}">${escapeHtml(w)}</button>`).join('')}</div><div style="height:8px"></div><div class="drag-answer" id="dragAnswer" aria-label="문장 단어를 놓는 곳"></div><div class="action-row" style="margin-top:10px"><button class="primary-button" data-action="check-order">문장 확인하기</button><button class="quiet-button" data-action="reset-order">처음부터</button></div><div class="inline-feedback" id="orderFeedback"></div></div>`}
