function lifeActivityTranslation(activity){return LIFE_ACTIVITY_KO[activity]||'이번 주말에 할 거야.'}
function lifeSentenceTranslation(sentence){const activity=String(sentence||'').replace(/^\d+\.\s*/,'').replace(/^I'm going to /,'').replace(/[.!?]$/,'');return lifeActivityTranslation(activity)}
function updateLifePromptCopy(){const prompt=$('#reviewGame .scenario-card + .control-label');if(prompt&&state.lifeIndex===0)prompt.textContent='어떤 선택이든 나만의 이야기가 이어져요. 마음에 드는 계획을 골라 보세요!'}
function addLifeTranslations(){const box=$('#reviewGame');if(!box)return;$$('.life-choice',box).forEach(button=>{if($('.life-choice-copy',button))return;const english=button.querySelector(':scope > span');if(!english)return;const copy=document.createElement('span');copy.className='life-choice-copy';const korean=document.createElement('small');korean.className='life-choice-translation';korean.textContent=lifeSentenceTranslation(english.textContent);copy.append(english,korean);button.prepend(copy)});$$('.life-story-entry',box).forEach(entry=>{if($('.life-choice-translation',entry))return;const sentence=$('.life-sentence',entry);if(!sentence)return;const korean=document.createElement('small');korean.className='life-choice-translation';korean.textContent=lifeSentenceTranslation(sentence.textContent);entry.insertBefore(korean,entry.querySelector('p'))});const reflection=$('#reflectionPrompt');if(reflection&&!$('.life-choice-translation',reflection.parentElement)){const korean=document.createElement('small');korean.className='life-choice-translation reflection-translation';const plan=lifeSentenceTranslation(state.lifeChoices[0]?.sentence||"I'm going to pack my space kit.");korean.textContent=`${state.stats.Happiness>60?'정말 멋진':'좋은'} 주말을 보냈어. ${plan}`;reflection.after(korean)}}
function lifeOptions(i){const options=[['walk the dog','stay home','buy a new toy'],['ride a bike','stay home','see a movie'],['play soccer','read a book','go shopping'],['save money','buy a snack','give a friend a treat'],['read a book','walk the dog','play soccer'],['visit my grandma','stay home','see a movie'],['see a movie','read a book','walk the dog'],['stay home','go shopping','play soccer'],['play soccer','stay home','see a movie'],['read a book','ride a bike','go shopping'],['ride a bike','stay home','see a movie'],['visit my grandma','walk the dog','stay home'],['go shopping','visit my grandma','stay home'],['read a book','play soccer','see a movie'],['walk the dog','stay home','ride a bike']];return options[i]}
function renderStep5(){stopCatchLoop();state.gameAIndex=0;state.gameAScore=0;state.catchLives=3;state.lifeIndex=0;state.stats={Money:50,Health:50,Happiness:50,Friendship:50};state.lifeChoices=[];const body=`<div class="subactivity-grid"><button class="activity-card" data-game="catch"><span class="activity-index">A</span><span class="step-arrow">↗</span><h3>단어 잡기</h3><p>떨어지는 단어 중 정답만 잡아요.</p></button><button class="activity-card" data-game="life"><span class="activity-index">B</span><span class="step-arrow">↗</span><h3>My Future Life</h3><p>15가지 선택으로 나의 미래를 만들어요.</p></button></div><div class="lesson-card" id="reviewGame"><div class="card-heading"><div><h3>어떤 게임부터 할까요?</h3><p>영어 문장을 사용하면 게임 속 미션이 열려요.</p></div><span class="pill">PLAY & REVIEW</span></div><div class="action-row"><button class="primary-button" data-game="catch">단어 잡기 시작</button><button class="secondary-button" data-game="life">인생게임 시작</button></div></div>`;shell(5,'복습게임','배운 표현을 게임 속에서 마음껏 사용해요.',body)}
const CATCH_QUESTIONS=[{before:"I'm going to ___ the dog.",answer:'walk',choices:['walk','walking','walked']},{before:'We are going to ___ a movie.',answer:'see',choices:['sees','see','seeing']},{before:'She is going to ___ home.',answer:'stay',choices:['stays','stayed','stay']},{before:'He is going to ___ soccer.',answer:'play',choices:['played','playing','play']},{before:"I'm going to ___ my grandma.",answer:'visit',choices:['visiting','visit','visits']}];
function startCatch(){stopCatchLoop();state.gameAIndex=0;state.gameAScore=0;state.catchLives=3;state.catchPlayerX=50;renderCatch()}
function stopCatchLoop(){state.catchActive=false;if(state.catchFrame)cancelAnimationFrame(state.catchFrame);if(state.catchTimer)clearTimeout(state.catchTimer);state.catchFrame=0;state.catchTimer=null}
function renderCatch(){stopCatchLoop();const box=$('#reviewGame');const q=CATCH_QUESTIONS[state.gameAIndex];if(!q){box.innerHTML=`<div class="catch-end"><span class="catch-end-mark">★</span><h3>Word Muncher 완료!</h3><p>${state.gameAScore} / ${CATCH_QUESTIONS.length}개 단어를 잡았어요. 정말 잘했어요!</p><div class="action-row"><button class="primary-button" data-game="catch">다시 도전</button><button class="secondary-button" data-action="home">홈으로</button></div></div>`;progressDone(5);return}if(state.catchLives<=0){box.innerHTML=`<div class="catch-end"><span class="catch-end-mark">↻</span><h3>한 번 더 해볼까요?</h3><p>이번에는 ${state.gameAScore}개를 잡았어요. 움직임을 잘 보고 정답을 노려봐요.</p><div class="action-row"><button class="primary-button" data-game="catch">다시 도전</button><button class="secondary-button" data-action="home">홈으로</button></div></div>`;return}box.innerHTML=`<div class="card-heading"><div><h3>Word Muncher · ${state.gameAIndex+1} / ${CATCH_QUESTIONS.length}</h3><p>정답 단어를 찾아 아래의 꼬마 몬스터에게 먹여주세요.</p></div><span class="score-chip" id="catchScore">잡은 단어 ${state.gameAScore}</span></div><div class="catch-hud"><span class="catch-round-label">WORD ${state.gameAIndex+1}</span><span class="catch-lives" id="catchLives"></span><span class="catch-hint">← → 키 또는 버튼으로 이동</span></div><div class="sentence-display catch-prompt">${q.before.replace('___','<span class="catch-blank">_____</span>')}<small>올바른 동사원형을 잡아 문장을 완성해요.</small></div><div class="catch-stage" id="catchStage" aria-label="단어를 잡는 게임 공간"><span class="catch-cloud catch-cloud-one"></span><span class="catch-cloud catch-cloud-two"></span><div class="catch-lane-lines"></div><div class="catch-word-layer" id="catchWords"></div><div class="catch-player" id="catchPlayer" style="left:${state.catchPlayerX}%" aria-label="단어를 먹는 캐릭터"><svg viewBox="0 0 92 76" aria-hidden="true"><path d="M17 25 8 7l22 10m45 8 9-18-22 10" fill="#79bd93" stroke="#428866" stroke-width="3" stroke-linejoin="round"/><ellipse cx="46" cy="43" rx="34" ry="29" fill="#91d4a8" stroke="#428866" stroke-width="3"/><ellipse cx="34" cy="38" rx="4" ry="6" fill="#2e5140"/><ellipse cx="58" cy="38" rx="4" ry="6" fill="#2e5140"/><circle cx="25" cy="48" r="5" fill="#f2a19a"/><circle cx="67" cy="48" r="5" fill="#f2a19a"/><path class="monster-mouth" d="M34 51c5 10 19 10 24 0" fill="#7c4f4b" stroke="#428866" stroke-width="3" stroke-linecap="round"/><path d="M39 55h14" stroke="#fff4d6" stroke-width="3" stroke-linecap="round"/></svg><span class="monster-name">MUNCH</span></div><div class="catch-overlay" id="catchOverlay"><span>세 단어가 곧 떨어져요!</span><button class="primary-button" data-action="catch-go">게임 시작</button></div><div class="catch-feedback" id="catchFeedback" aria-live="polite"></div></div><div class="catch-controls"><button class="catch-control" data-catch-move="-1" aria-label="왼쪽으로 이동">←</button><span>이동해서 정답만 잡아요!</span><button class="catch-control" data-catch-move="1" aria-label="오른쪽으로 이동">→</button></div><div class="catch-footnote">틀린 단어를 먹거나 정답을 놓치면 목숨이 줄어요.</div>`;renderCatchLives();bindCatchStage()}
function renderCatchLives(){const lives=$('#catchLives');if(lives)lives.innerHTML=Array.from({length:3},(_,i)=>`<span class="catch-heart ${i<state.catchLives?'alive':''}">●</span>`).join('')}
function beginCatchWave(){const stage=$('#catchStage');if(!stage||state.catchLives<=0)return;state.catchActive=true;state.catchLastFrame=0;$('#catchOverlay').hidden=true;$('#catchFeedback').textContent='';$('#catchPlayer').style.left=`${state.catchPlayerX}%`;const question=CATCH_QUESTIONS[state.gameAIndex];const choices=[...question.choices].sort(()=>Math.random()-.5);const lanes=[18,50,82].sort(()=>Math.random()-.5);state.catchTokens=choices.map((word,index)=>{const element=document.createElement('span');element.className='falling-word';element.textContent=word;element.style.left=`${lanes[index]}%`;$('#catchWords').append(element);return {word,correct:word===question.answer,x:lanes[index],y:-18-index*72,speed:140,element}});state.catchFrame=requestAnimationFrame(catchTick)}
function catchTick(time){if(!state.catchActive)return;const stage=$('#catchStage');if(!stage)return;const elapsed=state.catchLastFrame?Math.min((time-state.catchLastFrame)/1000,.05):0;state.catchLastFrame=time;const catchLine=stage.clientHeight-80;for(const token of [...state.catchTokens]){token.y+=token.speed*elapsed;token.element.style.top=`${token.y}px`;if(token.y>=catchLine&&Math.abs(token.x-state.catchPlayerX)<13){resolveCatchToken(token,true);return}if(token.y>stage.clientHeight-28){token.element.remove();state.catchTokens=state.catchTokens.filter(item=>item!==token);if(token.correct){resolveMissedAnswer();return}}}if(!state.catchTokens.length){beginCatchWave();return}state.catchFrame=requestAnimationFrame(catchTick)}
function resolveCatchToken(token,caught){stopCatchLoop();state.catchTokens.forEach(item=>item.element.remove());state.catchTokens=[];const player=$('#catchPlayer');player?.classList.toggle('munching',caught&&token.correct);if(token.correct){state.gameAScore++;$('#catchScore').textContent=`잡은 단어 ${state.gameAScore}`;$('#catchFeedback').textContent='냠! 정답이에요. 동사원형을 잘 찾았어요!';state.catchTimer=setTimeout(()=>{state.gameAIndex++;if(state.gameAIndex>=CATCH_QUESTIONS.length)renderCatch();else renderCatch()},900);return}state.catchLives--;renderCatchLives();$('#catchFeedback').textContent='앗, 그 단어는 문장에 맞지 않아요. 다음 단어를 살펴봐요!';if(state.catchLives<=0){state.catchTimer=setTimeout(renderCatch,900);return}state.catchTimer=setTimeout(beginCatchWave,850)}
function resolveMissedAnswer(){stopCatchLoop();state.catchTokens.forEach(item=>item.element.remove());state.catchTokens=[];state.catchLives--;renderCatchLives();$('#catchFeedback').textContent='정답이 지나갔어요! 다시 한 번 노려봐요.';if(state.catchLives<=0){state.catchTimer=setTimeout(renderCatch,900);return}state.catchTimer=setTimeout(beginCatchWave,850)}
function moveCatchPlayer(amount){if(!state.catchActive)return;state.catchPlayerX=Math.max(10,Math.min(90,state.catchPlayerX+amount));const player=$('#catchPlayer');if(player)player.style.left=`${state.catchPlayerX}%`}
function setCatchPlayerFromPointer(event){const stage=$('#catchStage');if(!stage||!state.catchActive)return;const rect=stage.getBoundingClientRect();state.catchPlayerX=Math.max(10,Math.min(90,((event.clientX-rect.left)/rect.width)*100));const player=$('#catchPlayer');if(player)player.style.left=`${state.catchPlayerX}%`}
function bindCatchStage(){const stage=$('#catchStage');if(!stage)return;stage.addEventListener('pointerdown',event=>{if(!state.catchActive||event.target.closest('button'))return;stage.setPointerCapture(event.pointerId);setCatchPlayerFromPointer(event)});stage.addEventListener('pointermove',event=>{if(state.catchActive&&(event.buttons||event.pointerType==='touch'))setCatchPlayerFromPointer(event)})}
function startLife(){state.lifeIndex=0;state.stats={Money:50,Health:50,Happiness:50,Friendship:50};state.lifeChoices=[];renderLife()}
function renderLife(){const box=$('#reviewGame');if(!box)return;if(state.lifeIndex>=LIFE_EVENTS.length){box.innerHTML=`<div class="card-heading"><div><h3>나의 미래 주말 이야기</h3><p>15가지 선택을 마쳤어요! 내가 만든 문장을 살펴봐요.</p></div><span class="pill">THE END</span></div><div class="stat-grid">${Object.entries(state.stats).map(([k,v])=>statHtml(k,v)).join('')}</div><div class="life-sentence-list">${state.lifeChoices.map((x,i)=>`<div class="life-sentence">${i+1}. ${x}</div>`).join('')}</div><div class="feedback-box"><h3>영어 소감 쓰기 도우미</h3><p id="reflectionPrompt">I had a ${state.stats.Happiness>60?'great':'nice'} weekend. I am going to ${state.lifeChoices[0]?.replace(/^I'm going to /,'').replace('.','')||'walk the dog'}.</p><button class="secondary-button" data-action="copy-reflection">소감 복사하기</button> <button class="quiet-button" data-action="print-notes">공책 인쇄하기</button></div><div class="action-row" style="margin-top:12px"><button class="primary-button" data-game="life">다시 시작</button></div>`;progressDone(5);return}const [title,description]=LIFE_EVENTS[state.lifeIndex];const options=lifeOptions(state.lifeIndex);box.innerHTML=`<div class="card-heading"><div><h3>My Future Life · ${state.lifeIndex+1} / 15</h3><p>내 선택이 주말의 이야기를 바꿔요.</p></div><span class="pill">CHOOSE YOUR PLAN</span></div><div class="stat-grid">${Object.entries(state.stats).map(([k,v])=>statHtml(k,v)).join('')}</div><div class="scenario-card"><span class="scenario-tag">LIFE MOMENT ${String(state.lifeIndex+1).padStart(2,'0')}</span><h3>${title}</h3><p>${description}</p></div><p class="control-label" style="margin-top:15px">무엇을 할까요? 문장을 선택한 뒤 단어 순서를 맞춰요.</p>${options.map((x,i)=>`<button class="life-choice" data-life-choice="${i}"><span>I'm going to ${x}.</span><small>선택 ${i+1} ↗</small></button>`).join('')}`}
function statHtml(name,value){return `<div class="stat"><div class="stat-name">${name}</div><div class="stat-value">${value}</div><div class="stat-meter"><span style="width:${value}%;background:${name==='Money'?'#e9bf5e':name==='Health'?'#78b9a2':name==='Happiness'?'#e99a8e':'#9b8acb'}"></span></div></div>`}
function lifeSelect(index){const activity=lifeOptions(state.lifeIndex)[index];const target=`I'm going to ${activity}.`;const words=target.replace('.','').split(' ');const shuffled=[...words].sort(()=>Math.random()-.5);const content=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-mark">✎</div><h2>문장을 완성해요</h2><p>단어를 순서대로 눌러 바른 문장을 만들어요.</p><div class="drag-bank" id="lifeBank" style="justify-content:center;margin:14px 0">${shuffled.map((w,i)=>`<button class="word-chip" data-life-word="${i}">${w}</button>`).join('')}</div><div class="drag-answer" id="lifeAnswer" style="justify-content:center"></div><div class="inline-feedback" id="lifeOrderFeedback"></div><div class="action-row"><button class="secondary-button" data-modal-close>취소</button><button class="primary-button" data-action="life-check" data-target="${target}">문장 완성!</button></div></div></div>`;document.body.insertAdjacentHTML('beforeend',content);const back=$('.modal-backdrop:last-child');back.dataset.correct=target;back.dataset.activity=activity;back.dataset.delta=JSON.stringify(getLifeDelta(activity,state.lifeIndex));}
function getLifeDelta(activity,index){const map={'walk the dog':{Health:8,Happiness:4},'see a movie':{Money:-7,Happiness:10,Friendship:5},'stay home':{Money:5,Health:3,Happiness:2},'play soccer':{Health:10,Friendship:7,Happiness:5},'visit my grandma':{Friendship:10,Happiness:6,Money:-3},'read a book':{Health:2,Happiness:6},'ride a bike':{Health:9,Happiness:5,Money:-2},'go shopping':{Money:-10,Happiness:5}};let d={...map[activity]||{Happiness:3}};if(index===3&&activity==='save money')d={Money:10,Happiness:2};if(index===3&&activity==='buy a snack')d={Money:-6,Happiness:3};if(index===3&&activity==='give a friend a treat')d={Money:-4,Friendship:8,Happiness:5};return d}
function startLifeStory(){state.lifeIndex=0;state.stats={Money:50,Health:50,Happiness:50,Friendship:50};state.lifeChoices=[];state.lastLifeStory='';renderLifeStory();updateLifePromptCopy();addLifeTranslations()}
function renderLifeStory(){const box=$('#reviewGame');if(!box)return;if(state.lifeIndex>=LIFE_STORIES.length){const firstPlan=state.lifeChoices[0]?.sentence.replace(/^I'm going to /,'').replace(/[.!?]$/,'')||'pack my space kit';box.innerHTML=`<div class="card-heading"><div><h3>나의 미래 주말 이야기</h3><p>15개의 선택으로 특별한 모험을 만들었어요.</p></div><span class="pill">THE END</span></div><div class="stat-grid">${Object.entries(state.stats).map(([key,value])=>statHtml(key,value)).join('')}</div><div class="life-story-list">${state.lifeChoices.map((choice,index)=>`<div class="life-story-entry"><div class="life-sentence">${index+1}. ${escapeHtml(choice.sentence)}</div><p>${escapeHtml(choice.outcome)}</p></div>`).join('')}</div><div class="feedback-box"><h3>영어 소감 쓰기 도우미</h3><p id="reflectionPrompt">I had a ${state.stats.Happiness>60?'great':'nice'} weekend. I am going to ${escapeHtml(firstPlan)}.</p><button class="secondary-button" data-action="copy-reflection">소감 복사하기</button> <button class="quiet-button" data-action="print-notes">공책 인쇄하기</button></div><div class="action-row" style="margin-top:12px"><button class="primary-button" data-game="life">다시 시작</button><button class="secondary-button" data-action="home">홈으로</button></div>`;progressDone(5);return}const event=LIFE_STORIES[state.lifeIndex];box.innerHTML=`<div class="card-heading"><div><h3>My Future Life · ${state.lifeIndex+1} / ${LIFE_STORIES.length}</h3><p>내 선택이 이야기를 바꿔요.</p></div><span class="pill">CHOOSE YOUR PLAN</span></div><div class="stat-grid">${Object.entries(state.stats).map(([key,value])=>statHtml(key,value)).join('')}</div>${state.lastLifeStory?`<div class="life-story-result"><span>지난 선택의 결과</span><p>${escapeHtml(state.lastLifeStory)}</p></div>`:''}<div class="scenario-card"><span class="scenario-tag">LIFE MOMENT ${String(state.lifeIndex+1).padStart(2,'0')}</span><h3>${escapeHtml(event.title)}</h3><p>${escapeHtml(event.description)}</p></div><p class="control-label" style="margin-top:15px">무엇을 할까요?</p>${event.choices.map((choice,index)=>`<button class="life-choice" data-life-choice="${index}"><span>I'm going to ${escapeHtml(choice.activity)}.</span><small>선택 ${index+1} →</small></button>`).join('')}`}
function lifeSelectStory(index){const choice=LIFE_STORIES[state.lifeIndex]?.choices[index];if(!choice)return;const target=`I'm going to ${choice.activity}.`;const words=target.replace('.','').split(' ');const shuffled=[...words].sort(()=>Math.random()-.5);const content=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-mark">Aa</div><h2>문장을 완성해요</h2><p>단어를 바르게 배열해요.</p><p class="life-modal-translation">${escapeHtml(lifeActivityTranslation(choice.activity))}</p><div class="drag-bank" id="lifeBank" style="justify-content:center;margin:14px 0">${shuffled.map((word,i)=>`<button class="word-chip" data-life-word="${i}">${escapeHtml(word)}</button>`).join('')}</div><div class="drag-answer" id="lifeAnswer" style="justify-content:center"></div><div class="inline-feedback" id="lifeOrderFeedback"></div><div class="action-row"><button class="secondary-button" data-modal-close>취소</button><button class="primary-button" data-action="life-story-check">문장 완성!</button></div></div></div>`;document.body.insertAdjacentHTML('beforeend',content);const modal=$('.modal-backdrop:last-child');modal.dataset.correct=target;modal.dataset.activity=choice.activity;modal.dataset.delta=JSON.stringify(choice.delta);modal.dataset.outcome=choice.outcome}
function finalizeLifeStory(sentence,activity,delta,outcome){Object.entries(delta).forEach(([key,value])=>state.stats[key]=Math.max(0,Math.min(100,state.stats[key]+value)));state.lifeChoices.push({sentence,outcome});state.lastLifeStory=outcome;state.lifeIndex++;renderLifeStory();updateLifePromptCopy();addLifeTranslations();showToast('선택한 계획대로 이야기가 이어졌어요.')}

