 if(target.matches('[data-action="check-order"]')){const formed=state.placedWords.map(i=>state.dragWords[i]).join(' ');const correct=state.recommendation.replace(/[.!?]/g,'');$('#orderFeedback').textContent=normalize(formed)===normalize(correct)?'완벽해요! 단어 순서를 정확하게 맞췄어요.':'괜찮아요. 추천 문장을 다시 보고 단어 순서를 바꿔봐요.';if(normalize(formed)===normalize(correct))progressDone(4);return}
